from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe');base='ba110b4cf910d6bfe32a24999e8da7f746219973';target=repo/'jobctl.py';test=repo/'tests/test_jobctl_review_metrics_latest.py'
def git(*a):return subprocess.run(['git',*a],cwd=repo,text=True,capture_output=True,check=True).stdout.strip()
if git('rev-parse','HEAD')!=base or git('rev-parse','origin/main')!=base:raise SystemExit('AUTHORITY_CHANGED')
for f in (target,test):
 if git('status','--porcelain','--',str(f.relative_to(repo))):raise SystemExit('TARGET_DIRTY')
s=target.read_text()
old='''    supported_runs: set[str] = set()
    model_calls: list[int] = []'''
new='''    model_calls: list[int] = []'''
if s.count(old)!=1:raise SystemExit('SET_ANCHOR_CHANGED')
s=s.replace(old,new,1)
old='''        if adapter in SUPPORTED_ATS and run_id:
            supported_runs.add(run_id)
            # Count only the latest authoritative state, not an old Review
            # later invalidated by a correction or failed verification.'''
if s.count(old)!=1:raise SystemExit('ADAPTER_ANCHOR_CHANGED')
s=s.replace(old,'',1)
old='''    review_runs = {
        run_id for run_id in supported_runs'''
new='''    # A later correction without an adapter name must retain the previous
    # run's ATS identity, while later explicit adapter changes take precedence.
    supported_runs = {
        run_id for run_id, adapter in run_adapters.items()
        if adapter in SUPPORTED_ATS
    }
    review_runs = {
        run_id for run_id in supported_runs'''
if s.count(old)!=1:raise SystemExit('METRIC_ANCHOR_CHANGED')
s=s.replace(old,new,1)
old='''    latest: dict[str, dict[str, Any]] = {}
    review_runs: set[str] = set()'''
new='''    latest: dict[str, dict[str, Any]] = {}
    run_adapters: dict[str, str] = {}'''
if s.count(old)!=1:raise SystemExit('LATEST_ANCHOR_CHANGED')
s=s.replace(old,new,1)
old='''        adapter = str(outcome.get("adapter") or "")
        details = outcome.get("details")'''
new='''        adapter = str(outcome.get("adapter") or "")
        if adapter and run_id:
            run_adapters[run_id] = adapter
        details = outcome.get("details")'''
if s.count(old)!=1:raise SystemExit('DETAILS_ANCHOR_CHANGED')
s=s.replace(old,new,1);target.write_text(s)
t=test.read_text()
t+='''
def test_newer_non_ats_adapter_does_not_inflate_supported_run_rate():
    result=_event_metrics([
        event("a","REVIEW_READY","greenhouse"),
        event("a","REVIEW_READY","unsupported"),
        event("b","REVIEW_READY","ashby"),
    ])["supported_ats_review_arrival"]
    assert result=={"reached":1,"runs":1,"rate":1.0}

def test_correction_without_adapter_keeps_run_identity():
    result=_event_metrics([
        event("a","REVIEW_READY","greenhouse"),
        event("a","NEEDS_USER",""),
    ])["supported_ats_review_arrival"]
    assert result=={"reached":0,"runs":1,"rate":0.0}
'''
test.write_text(t)
p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','tests/test_jobctl_review_metrics_latest.py'],cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
try:o,e=p.communicate(timeout=110)
except subprocess.TimeoutExpired:
 os.killpg(p.pid,signal.SIGKILL);raise SystemExit('TIMEOUT')
print('RESULT',p.returncode,o[-2600:],e[-700:],flush=True)
if p.returncode:raise SystemExit('TEST_FAILED')
subprocess.run(['git','add','--','jobctl.py','tests/test_jobctl_review_metrics_latest.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','fix: attribute ATS Review metrics to latest recorded adapter identity'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD'),flush=True)
